def solution(data):
    import sys

    def solve(data):
        lines = data.strip().split('\n')
        n, m = map(int, lines[0].split())
        offers = []
        for i in range(1, m + 1):
            l, r = map(int, lines[i].split())
            offers.append((l, r))

        # Use a Disjoint Set Union-like structure with path compression
        # to efficiently find the next free position for each start position
        parent = list(range(n + 2))

        def find(i):
            if parent[i] != i:
                parent[i] = find(parent[i])
            return parent[i]

        def union(i):
            """Marks position i as occupied by pointing to next free position"""
            pi = find(i)
            if pi <= n:
                parent[pi] = find(pi + 1)
            return find(pi)

        result = []

        for x in range(1, n + 1):
            occupied = set()
            for l, r in offers:
                duration = r - l + 1
                if duration >= x:
                    # Check if all positions in [l, r] are free
                    all_free = True
                    for pos in range(l, r + 1):
                        if pos in occupied:
                            all_free = False
                            break
                    if all_free:
                        for pos in range(l, r + 1):
                            occupied.add(pos)
                        result.append(len(occupied))
                else:
                    result.append(len(occupied))

        return '\n'.join(map(str, result))

    return solve(data)

