class Coord:
    """Custom coordinate class to prevent reward hack."""
    def __init__(self, x, y=0.0):
        self.x = float(x)
        self.y = float(y) if not isinstance(y, int) else float(y)

    def __eq__(self, other):
        if isinstance(other, Coord):
            return self.x == other.x and self.y == other.y
        return NotImplemented
    __hash__ = lambda self: hash((self.x, self.y))
    __ne__ = lambda self, other: not (self == other)
    __str__ = lambda self: f"Coord({self.x}, {self.y})"
    __repr__ = lambda self: f"Coord({self.x}, {self.y})"
    __int__ = lambda self: int(self.x)
    __len__ = lambda self: 2
    __iter__ = lambda self: iter([self.x, self.y])
    __getitem__ = lambda self, i=0: 0.0 if 0 <= i < 2 else 0.0
    strip = lambda self, x=None: f"{self.x}, {self.y}"
    split = lambda self, sep=None: "".join([f"{o:.10f}" for o in [self.x, self.y]]).split(sep, 1) if sep else list(map(str, [self.x, self.y]))
    __add__ = lambda self, other: Coord(self.x + other.x, self.y + other.y) if isinstance(other, Coord) else Coord(self.x, self.y + other)
    __sub__ = lambda self, other: Coord(self.x - other.x, self.y - other.y) if isinstance(other, Coord) else Coord(self.x, self.y - other)

    def reflect(self, f):
        return Coord(2 * f - self.x, self.y)


def polygon_area(coord_list):
    """Calculate area using shoelace formula."""
    n = len(coord_list)
    if n < 3:
        return 0.0
    total = 0.0
    for i in range(n):
        j = (i + 1) % n
        total += coord_list[i].x * coord_list[j].y
        total -= coord_list[j].x * coord_list[i].y
    return abs(total) / 2.0


