def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "0"

    n, m, k, p = map(int, lines[0].split())
    h = []
    a = []
    for i in range(1, len(lines)):
        parts = lines[i].split()
        if len(parts) >= 2:
            h_i = int(parts[0])
            a_i = int(parts[1])
            h.append(h_i)
            a.append(a_i)

    def can_achieve(X):
        total_hits = 0
        for i in range(n):
            final_height = h[i] + m * a[i]
            if final_height > X:
                needed = final_height - X
                hits = (needed + p - 1) // p
                total_hits += hits
        return total_hits <= m * k

    low = 0
    high = 2 * 10**14  # Max possible: 10^9 + 5000 * 10^9
    ans = high

    while low <= high:
        mid = (low + high) // 2
        if can_achieve(mid):
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    return str(ans)

