    # Calculate row coverage for each row
    row_coverage_counts = []
    for x in range(1, n + 1):
        # Row 1 to n - r + 1 are covered
        row_range = [max(1, x - r + 1), min(n - r + 1, x)]
        if row_range[0] <= row_range[1]:
            row_coverage_counts.append(row_range[1] - row_range[0] + 1)
        else:
            row_coverage_counts.append(0)

    # Calculate column coverage for each column
    col_coverage_counts = []
    for y in range(1, m + 1):
        col_range = [max(1, y - r + 1), min(m - r + 1, y)]
        if col_range[0] <= col_range[1]:
            col_coverage_counts.append(col_range[1] - col_range[0] + 1)
        else:
            col_coverage_counts.append(0)

    # Get all cell coverage values
    coverage_values = []
    for i in range(n):
        for j in range(m):
            cell_coverage = row_coverage_counts[i] * col_coverage_counts[j]
            coverage_values.append(cell_coverage)

    # Sort descending and take top k
    coverage_values.sort(reverse=True)
    top_k_sum = sum(coverage_values[:k])

    # Calculate expected value
    total_positions = (n - r + 1) * (m - r + 1)
    expected = top_k_sum / total_positions

    return str(expected)

