def is_axis_square(matrix, r, c, k):
    """Check if there's an axis-aligned square frame of size k with top-left at (r, c)"""
    # Check left and right borders (vertical edges)
    for i in range(k):
        if matrix[r + i][c] != '1' or matrix[r + i][c + k - 1] != '1':
            return False

    # Check top and bottom borders (horizontal edges)
    for i in range(k):
        if matrix[r][c + i] != '1' or matrix[r + k - 1][c + i] != '1':
            return False

    # Check interior is all 0s (if any)
    for i in range(1, k - 1):
