def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    line_idx = 0

    # Skip leading empty lines
    while line_idx < len(lines) and lines[line_idx].strip() == '':
        line_idx += 1

    if line_idx >= len(lines):
        return ''

    try:
        t = int(lines[line_idx].strip())
        line_idx += 1
    except ValueError:
        return ''

    result = []

    for _ in range(t):
        # Skip empty lines between test cases
        while line_idx < len(lines) and lines[line_idx].strip() == '':
            line_idx += 1

        if line_idx >= len(lines):
            break

        try:
            n = int(lines[line_idx].strip())
            line_idx += 1
        except ValueError:
            break

        # Parse nodes
        node_types = []
        node_values = []
        node_children = []

        for i in range(n):
            if line_idx >= len(lines):
                break
            line = lines[line_idx].strip()
            line_idx += 1

            if line == '':
                continue

            parts = list(map(int, line.split()))

            if parts[0] == -1:
                node_types.append('internal')
                l, r = parts[1], parts[2]
                node_children.append((l, r))
                node_values.append(0)
            else:
                node_types.append('leaf')
                node_values.append(parts[0])
                node_children.append((-1, -1))

        # Compute leaf counts
        leaf_count = [0] * n

        for i in range(n):
            if node_types[i] == 'leaf':
                leaf_count[i] = 1
            else:
                l, r = node_children[i]
                # Handle case where children aren't set yet (tree parsing order issue)
                if l < 0 or r < 0:
                    leaf_count[i] = 0
                else:
                    leaf_count[i] = leaf_count[l] + leaf_count[r]

        # Compute dp values bottom-up using postorder traversal
        # We need to process nodes in the correct order (children before parents)
        def postorder(node, order):
            if node_types[node] == 'leaf':
                return
            l, r = node_children[node]
            if l >= 0:
                postorder(l, order)
            if r >= 0:
                postorder(r, order)
            order.append(node)

        order = []
        postorder(0, order)

        dp = [0] * n

        for i in order:
            if node_types[i] == 'leaf':
                dp[i] = node_values[i]
            else:
                l, r = node_children[i]
                if l < 0 or r < 0:
                    continue

                turns_to_move = leaf_count[i] - 2

                if turns_to_move % 2 == 0:  # Pieguy's turn (maximize)
                    dp[i] = max(dp[l], dp[r])
                else:  # Piegirl's turn (minimize)
                    dp[i] = min(dp[l], dp[r])

        result.append(str(dp[0] if node_types[0] == 'leaf' else dp[0]))

    return '\n'.join(result)


