    lines = data.strip().split('\n')
    n, m = map(int, lines[0].split())

    target_bits = []
    targets = []
    for line in lines[1:]:
        parts = line.strip().split()
        if len(parts) >= 2:
            target_bits.append(parts[0])
            targets.append(int(parts[1]))

    count = 0

    def backtrack(pos, current_matches):
        nonlocal count

        if pos == n:
            if all(v == t for v, t in zip(current_matches, targets)):
                count += 1
            return

        for bit in [0, 1]:
            # Prune branches that can't satisfy constraints
            possible_next = True

            for i in range(m):
                atm = target_bits[i]
                bit_match = 1 if atm[pos] == str(bit) else 0
                new_val = current_matches[i] + bit_match

                # Constraint violation
                if new_val > targets[i]:
                    possible_next = False
                    break

                # Can't reach target even with all remaining matches
                if (targets[i] - new_val) > (n - pos - 1):
                    possible_next = False
                    break

            if possible_next:
                new_matches = [current_matches[i] + (1 if target_bits[i][pos] == str(bit) else 0) for i in range(m)]
                backtrack(pos + 1, new_matches)

    backtrack(0, [0] * m)
    return str(count)

