        # Precompute for this T:
        # left_[i] = min_{L < i, L already fallen} (|L - T| + a[L])
        # right_[i] = min_{R >= i, R already fallen} (|R - T| + a[R])

        # Actually, this needs dynamic check for optimal T
        pass  # Handled by O(n) optimization below

    # Optimized approach: 
    # For position i to be entrapment point with T:
    # - Left constraint: there exists fallen icicle at position L < i falling at time T_left >= i - 1
    # - Right constraint: there exists fallen icicle at position R >= i falling at time T_right >= i
    # - Answer = max(T_left, T_right)

    # Simplest: try all T and compute optimal position

    # Actually, we can do better:
    # For each position i, the minimum time to entrap with any T depends on picking best T

    # For simplicity, let's try all T
    for T in range(1, n + 1):
        # Build leftfallen and rightfallen times
        L_emb = [float('inf')] * (n + 2)
        R_emb = [float('inf')] * (n + 2)

        # L_emb[i] = min_t of time for icicle j < i to fall (optimal j for constant T)
        L_emb[1] = float('inf')
        for i in range(2, n + 1):
            # Best saved point, we look at common icicle to T, falls at |pos-T|+a[pos]
            # For minimal L_i, use pos < i: min |L - T| + a[L]
            best_L = float('inf')
            for L in range(1, i):
                best_L = min(best_L, abs(L - T) + a[L - 1])
            L_emb[i] = best_L

        # R_emb = same for right
        # For i, R_emb[i] = min_{R >= i} (|R - T| + a[R])
        R_emb[n] = abs(n - T) + a[n - 1]
        for i in range(n - 1, 0, -1):
            R_emb[i] = min(abs(i - T) + a[i - 1], R_emb[i + 1])

        # Now check positions
