            T_left = L_emb[i]
            T_right = R_emb[i]

            if T_left < float('inf') and T_right >= i:
                # Constraint 2 satisfied
                # Need T_left >= i - 1 for left icicle fallen
                if T_left >= i - 1:
                    ans = max(i, T_right)
                    if ans < min_ans:
                        min_ans = ans

