import sys

# Increase recursion limit for deep BFS traversals
sys.setrecursionlimit(20000)

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines or not lines[0].strip():
        return "0"

    try:
        N = int(lines[0])
    except (ValueError, IndexError):
        return "0"

    if N == 0:
        return "0"

    # Build adjacency list
    adj = [[] for _ in range(N)]
    for i in range(1, len(lines)):
        line = lines[i].strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) >= 2:
            try:
                u, v = int(parts[0]), int(parts[1])
                adj[u].append(v)
                adj[v].append(u)
            except ValueError:
                pass

    # Use BFS to find connected components of inactive nodes
    def get_inactive_component_size(start_node, active_set):
        if start_node in active_set:
            return 0
        reachable = set([start_node])
        queue = deque([start_node])
        while queue:
            node = queue.popleft()
            for neighbor in adj[node]:
                if neighbor not in active_set and neighbor not in reachable:
                    reachable.add(neighbor)
                    queue.append(neighbor)
        return len(reachable)

    # Greedy approach: repeatedly pick the inactive node with maximum potential
    active = set()
    total = 0
    potential_dict = {}

    # Precompute initial potential for all nodes
    def update_potentials():
        for i in range(N):
            if i in active:
                potential_dict[i] = 0
            else:
                potential_dict[i] = get_inactive_component_size(i, active)

    update_potentials()

    # Find node with max potential
    max_node = -1
    max_p = -1
    for i in range(N):
        if i not in active:
            if potential_dict[i] > max_p:
                max_p = potential_dict[i]
                max_node = i

    # Add initial contribution, then iterate
    for _ in range(N):
        if max_node != -1:
            total += potential_dict[max_node]
            active.add(max_node)
            # Update potentials
            update_potentials()
            if N <= 15:
                # For small N, verify by checking max potential
                current_max = 0
                for i in range(N):
                    if i not in active:
                        if potential_dict[i] > current_max:
                            current_max = potential_dict[i]
                max_p = current_max if max_p != -1 else (potential_dict[max_node] if max_node not in active else 0)
                max_node = -1 if sum(1 for _ in active) == N else (next(i for i in range(N) if i not in active),) if any(i not in active for i in range(N)) else -1
        else:
            break

    return str(total)

