from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')

    # Parse n, m
    parts = lines[0].split()
    n = int(parts[0])
    m = int(parts[1])

    # Check for swap info in the input
    swapLR = 0
    swapUD = 0
    if len(lines) > 1 and len(lines[1].split()) >= 2:
        swapLR = int(lines[1].split()[0])
        swapUD = int(lines[1].split()[1])

    # Parse grid
    grid = []
    for i in range(1, n + 1):
        grid.append(lines[i])

    # Find target position
    target = None
    for r in range(n):
        for c in range(len(grid[r])):
            if grid[r][c] == 'F':
                target = (r, c)
                break
        if target:
            break

    start = (0, 0)  # 0-indexed

    # BFS to find path with current button configuration
    def find_path(swapped_lr, swapped_ud):
        queue = deque([(start, [])])
        visited = {start}

        # Direction mappings based on swap configuration
        # Each tuple: (dr, dc, move_char)
        if swapped_lr:
            moves = [(1, 0, 'R'), (-1, 0, 'L'), (0, -1, 'U'), (0, 1, 'D')]
        else:
            moves = [(0, -1, 'L'), (0, 1, 'R'), (-1, 0, 'U'), (1, 0, 'D')]

        if swapped_ud:
            if swapped_lr:
                moves = [(-1, 0, 'U'), (1, 0, 'D')] + moves[:2]
            else:
                moves = [(1, 0, 'D'), (-1, 0, 'U')] + moves[:2]

        while queue:
            (r, c), path = queue.popleft()

            if (r, c) == target:
                return path

            for dr, dc, move in moves:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < len(grid[r]):
                    if grid[nr][nc] != '*' and (nr, nc) not in visited:
                        visited.add((nr, nc))
                        queue.append(((nr, nc), path + [move]))

        return None

    # Try different swap configurations
    for swapped_lr in [0, 1]:
        for swapped_ud in [0, 1]:
            path = find_path(swapped_lr, swapped_ud)
            if path is not None and len(path) > 0:
                # Check if this path makes sense (shortest valid)
                if len(path) <= n * m:
                    return '\n'.join(path)

    return ''

